INSERT INTO "public"."aulas" ("id", "disciplina_id", "data", "conteudo", "professor_id", "created_at", "turma_disciplina_id") VALUES ('697abf1a-40e2-4759-a254-b9f5ccaabdb8', NULL, '2026-07-06', 'Aula expositiva via google meet sobre os conceitos de ética, moral, bioética e deontologia, abordando suas diferenças e aplicações na prática da enfermagem. Foram discutidos os princípios fundamentais da bioética (autonomia, beneficência, não maleficência e justiça), seguidos de um debate em sala com análise de situações-problema, estimulando a participação ativa, o pensamento crítico e a reflexão ética dos estudantes.', 'd0bfc31d-c7b5-4187-8c8c-96cdf57e61f6', NULL, 'aee96da8-c7c7-4efe-b549-60458c6396d5');
INSERT INTO "public"."aulas" ("id", "disciplina_id", "data", "conteudo", "professor_id", "created_at", "turma_disciplina_id") VALUES ('33e6de2c-4dde-4341-bf97-da19558b0ebc', NULL, '2026-07-07', 'Registro de frequência + Atividade avaliativa individual sobre os conceitos de ética, moral, bioética, deontologia e os princípios da bioética, realizada em sala de aula com tempo cronometrado (19h30 às 21h30). A atividade teve como objetivo verificar a compreensão dos conteúdos abordados, estimular a reflexão crítica e a aplicação dos conceitos em situações relacionadas à prática da enfermagem. A entrega foi obrigatória até o final da aula.
